#pragma once

#include "components/core/memory.hpp"

#include <fstream>
#include <cstring>

namespace
{
    template<typename T>
    void write_memory(memory& mem, const std::vector<T>& bytes)
    {
        std::memcpy(mem.mem.begin() + mem.program_start_byte, bytes.data(), bytes.size());
    }
}

void load_rom_from_path(memory& mem, const std::string& path)
{
    std::ifstream input(path, std::ios::binary);

    std::vector<char> bytes((std::istreambuf_iterator<char>(input)), (std::istreambuf_iterator<char>()));

    input.close();

    write_memory(mem, bytes);
}

